//! Multi-route SSR router: maps URL paths to .crepus templates.
use std::collections::HashMap;
use std::sync::Arc;

use axum::{
    extract::{Path, State},
    response::Html,
    routing::get,
    Router,
};
use crepuscularity_core::ast::Node;
use crepuscularity_core::TemplateContext;
use crepuscularity_web::{render_ssr_document, SsrDocument};

/// Escape HTML special characters in error messages before injecting into HTML.
fn escape_html_error(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
}

/// A single route entry pairing a template source with a page title.
///
/// The `nodes` field holds the pre-parsed AST so templates are not re-parsed on every request.
pub struct RouteEntry {
    pub template: String,
    pub title: String,
    /// Pre-parsed template AST, cached at startup to avoid re-parsing on every request.
    pub nodes: Arc<Vec<Node>>,
}

/// Builds an Axum `Router` from a declarative map of URL paths → `.crepus` templates.
///
/// Templates are pre-parsed at registration time (in [`SsrRouter::route`]) so that parse errors
/// surface immediately at startup and the parsed AST is reused across all requests.
///
/// # Example
/// ```rust,no_run
/// use crepuscularity_ssr::SsrRouter;
///
/// let router = SsrRouter::new()
///     .route("/", r#"div "Home""#, "Home")
///     .route("/about", r#"div "About""#, "About")
///     .into_axum_router();
/// ```
pub struct SsrRouter {
    routes: HashMap<String, RouteEntry>,
}

impl Default for SsrRouter {
    fn default() -> Self {
        Self::new()
    }
}

impl SsrRouter {
    pub fn new() -> Self {
        Self {
            routes: HashMap::new(),
        }
    }

    /// Register a URL path with its template source and page title.
    ///
    /// The template is pre-parsed immediately so that syntax errors are caught at startup
    /// rather than at request time. The parsed AST is stored in [`RouteEntry::nodes`] and
    /// shared across all requests via `Arc`.
    pub fn route(
        mut self,
        path: &str,
        template: impl Into<String>,
        title: impl Into<String>,
    ) -> Self {
        let template = template.into();
        let title = title.into();
        let nodes = crepuscularity_core::ast_cache::parse_content(&template).unwrap_or_else(|e| {
            panic!("SsrRouter::route: failed to parse template for {path}: {e}")
        });
        self.routes.insert(
            path.to_string(),
            RouteEntry {
                template,
                title,
                nodes,
            },
        );
        self
    }

    /// Build an Axum [`Router`] from the registered routes.
    pub fn into_axum_router(self) -> Router {
        let routes = Arc::new(self.routes);
        Router::new()
            .route("/*path", get(handle_route))
            .route("/", get(handle_root))
            .with_state(routes)
    }
}

async fn handle_root(State(routes): State<Arc<HashMap<String, RouteEntry>>>) -> Html<String> {
    render_entry(&routes, "/").await
}

async fn handle_route(
    State(routes): State<Arc<HashMap<String, RouteEntry>>>,
    Path(path): Path<String>,
) -> Html<String> {
    let path = format!("/{path}");
    render_entry(&routes, &path).await
}

/// Look up the route entry and render the template on a blocking thread so the async
/// runtime event loop is not stalled by synchronous template parsing/rendering.
async fn render_entry(routes: &HashMap<String, RouteEntry>, path: &str) -> Html<String> {
    let entry = match routes.get(path).or_else(|| routes.get("/")) {
        Some(e) => e,
        None => return Html("<h1>404 Not Found</h1>".to_string()),
    };
    let template = entry.template.clone();
    let title = entry.title.clone();

    // Wrap the synchronous parsing/rendering work in spawn_blocking so it runs on a
    // dedicated blocking thread instead of stalling the Tokio async runtime.
    let result = tokio::task::spawn_blocking(move || {
        let ctx = TemplateContext::new();
        let doc = SsrDocument {
            title: &title,
            ..Default::default()
        };
        render_ssr_document(&template, &ctx, &doc, true)
    })
    .await;

    match result {
        Ok(Ok(h)) => Html(h),
        Ok(Err(e)) => Html(format!(
            "<pre style='color:red'>{}</pre>",
            escape_html_error(&e.to_string())
        )),
        Err(e) => Html(format!(
            "<pre style='color:red'>render task panicked: {}</pre>",
            escape_html_error(&e.to_string())
        )),
    }
}

/// `crepus dev` — hot-reload dev loop.
///
/// Thread layout:
///   main thread  → GPUI Application::run (owns DevHUD window, blocks until closed)
///   background   → file watcher + cargo build + child process management
///
/// Communication: `Arc<Mutex<HudState>>` (polled by GPUI entity every 100ms)
/// Shutdown:      `Arc<AtomicBool>` set when GPUI window closes
///
/// When `--emit-events` is passed, emits structured JSON CompilerEvents to stdout
/// for IDE/editor integration (following Equilibrium HotCompiler pattern).
use std::path::PathBuf;
use std::process::{Child, Command};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use notify::{recommended_watcher, Event, EventKind, RecursiveMode, Watcher};

use crate::build_options::BuildOptions;
use crate::builder::{cargo_build, find_bin_name, kill_child};
use crate::events::CompilerEvent;
use crate::hud::{open_hud_window, DevStatus, HudState};
use crate::ui;

pub fn run(bin_override: Option<String>, options: BuildOptions, emit_events: bool) {
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));

    let bin_name = find_bin_name(&cwd, bin_override.as_deref()).unwrap_or_else(|| {
        ui::error("could not determine binary name — add [[bin]] to Cargo.toml or use --bin");
    });

    let shared = Arc::new(Mutex::new(HudState::new(bin_name.clone())));
    let shutdown = Arc::new(AtomicBool::new(false));

    // Emit server started event
    if emit_events {
        CompilerEvent::dev_server_started(
            bin_name.clone(),
            vec![cwd.join("src"), cwd.join("Cargo.toml")],
        )
        .emit();
    }

    // Spawn background build+watch thread
    {
        let shared = shared.clone();
        let shutdown = shutdown.clone();
        let cwd = cwd.clone();
        let bin_name = bin_name.clone();
        std::thread::spawn(move || {
            background_loop(shared, shutdown, cwd, bin_name, options, emit_events)
        });
    }

    // Run GPUI DevHUD on main thread (blocks until window is closed)
    {
        let shared = shared.clone();
        let shutdown = shutdown.clone();
        gpui::Application::new().run(move |cx: &mut gpui::App| {
            open_hud_window(shared, shutdown, cx);
        });
    }

    // Window closed — tell background thread to stop
    shutdown.store(true, Ordering::Relaxed);
}

// ── Background loop ────────────────────────────────────────────────────────

fn background_loop(
    shared: Arc<Mutex<HudState>>,
    shutdown: Arc<AtomicBool>,
    cwd: PathBuf,
    bin_name: String,
    options: BuildOptions,
    emit_events: bool,
) {
    let (tx, rx) = std::sync::mpsc::channel::<PathBuf>();
    let tx_notify = tx.clone();

    let mut watcher = match recommended_watcher(move |res: notify::Result<Event>| {
        if let Ok(ev) = res {
            match ev.kind {
                EventKind::Modify(_) | EventKind::Create(_) | EventKind::Remove(_) => {
                    // Send the first changed path for event emission
                    if let Some(path) = ev.paths.into_iter().next() {
                        let _ = tx_notify.send(path);
                    }
                }
                _ => {}
            }
        }
    }) {
        Ok(w) => w,
        Err(e) => {
            eprintln!("  {} could not create file watcher: {e}", crate::ui::err());
            return;
        }
    };

    let src = cwd.join("src");
    if src.exists() {
        watcher.watch(&src, RecursiveMode::Recursive).ok();
    }
    watcher
        .watch(&cwd.join("Cargo.toml"), RecursiveMode::NonRecursive)
        .ok();

    // Initial build + launch
    let mut child = do_build_launch(&shared, &cwd, &bin_name, options, None, emit_events);

    loop {
        if shutdown.load(Ordering::Relaxed) {
            if let Some(mut c) = child {
                kill_child(&mut c);
                if emit_events {
                    CompilerEvent::process_exited(c.id(), None).emit();
                }
            }
            break;
        }

        match rx.recv_timeout(Duration::from_millis(200)) {
            Ok(changed_path) => {
                // Emit file changed event
                if emit_events {
                    CompilerEvent::file_changed(changed_path).emit();
                }

                // Debounce: drain events for 300 ms
                let t = Instant::now();
                while t.elapsed() < Duration::from_millis(300) {
                    while rx.try_recv().is_ok() {}
                    std::thread::sleep(Duration::from_millis(30));
                }
                eprintln!("  {} change detected — rebuilding…", crate::ui::arrow());
                child = do_build_launch(&shared, &cwd, &bin_name, options, child, emit_events);
            }
            Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {
                // Check whether child exited on its own
                if let Some(ref mut c) = child {
                    match c.try_wait() {
                        Ok(Some(status)) => {
                            let code = status.code();
                            eprintln!("  {} app exited ({code:?})", crate::ui::warn());
                            if emit_events {
                                CompilerEvent::process_exited(c.id(), code).emit();
                            }
                            if let Ok(mut s) = shared.lock() {
                                s.status = DevStatus::Exited { code };
                            }
                            child = None;
                            if code.is_some() {
                                break;
                            }
                        }
                        Ok(None) => {}
                        Err(_) => child = None,
                    }
                }
            }
            Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => break,
        }
    }
}

/// Find the compiled binary, checking the workspace root target dir first.
///
/// In a workspace, `cargo build` places binaries in `{workspace_root}/target/`
/// rather than in the crate's own directory. We use `cargo locate-project
/// --workspace` to find the workspace root, then fall back to `{cwd}/target/`.
fn locate_binary(cwd: &std::path::Path, profile: &str, bin_name: &str) -> PathBuf {
    // Ask cargo where the workspace root is
    let workspace_root = std::process::Command::new("cargo")
        .args(["locate-project", "--workspace", "--message-format", "plain"])
        .current_dir(cwd)
        .output()
        .ok()
        .and_then(|out| {
            if out.status.success() {
                let s = String::from_utf8(out.stdout).ok()?;
                let p = PathBuf::from(s.trim());
                p.parent().map(|d| d.to_path_buf())
            } else {
                None
            }
        });

    let target_base = workspace_root.unwrap_or_else(|| cwd.to_path_buf());
    target_base.join("target").join(profile).join(bin_name)
}

